import type { EnemyCharacterEntry, QuestAiEntry } from "../types";

// Generated from BossRushReferenceExporter output and bundled for offline/GitHub Pages use.
const encodedCatalog = [
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
].join("");

function decodeCatalog(): { characters: EnemyCharacterEntry[]; questAi: QuestAiEntry[] } {
  const binary = atob(encodedCatalog);
  const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0));
  return JSON.parse(new TextDecoder().decode(bytes));
}

export const builtInCatalog = decodeCatalog();

